import { ParentComponent, splitProps } from "solid-js";

import {
	Tooltip,
	TooltipBaseProps,
	TooltipHorizontalPosition,
	TooltipVerticalPosition,
} from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { type UnitInfoSectionProps } from "#base/ui-next/tooltips/plot-tooltip/helpers.js";
import { UnitInfoSection } from "#base/ui-next/tooltips/plot-tooltip/plot-tooltip.js";

interface UnitFlagTooltipProps extends Omit<TooltipBaseProps, "initialVPosition" | "initialHPosition" | "offset"> {
	unitInfo: UnitInfoSectionProps;
	initialVPosition?: TooltipVerticalPosition;
	initialHPosition?: TooltipHorizontalPosition;
	offset?: number;
}

export const UnitFlagTooltipComponent: ParentComponent<UnitFlagTooltipProps> = (props) => {
	const [local, other] = splitProps(props, ["children", "class", "unitInfo"]);
	return (
		<Tooltip {...other}>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content class={local.class}>
				<Tooltip.Frame>
					<UnitInfoSection {...local.unitInfo} />
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const UnitFlagTooltip = ComponentRegistry.register({
	name: "UnitFlagTooltip",
	createInstance: UnitFlagTooltipComponent,
	images: ["blp:base_ticket-bg", "blp:shell_line-divider"],
});
